def name_operands(region,address,operation):
    if (region,address)!=('Action',0x6C43):return operation
    for value,name in ((0xD9B6,'Output0'),(0xD7C4,'Output1'),(0xD7A2,'Output2')):
        operation=operation.replace('(#'+format(value,'04X')+')','(@ActionPatchedVectorState.'+name+')')
    for value,name in ((0x9B1F,'Component0'),(0x9B22,'Component1'),(0x9B25,'Component2')):
        operation=operation.replace('(#'+format(value,'04X')+')','(@ActionComponentWork.'+name+'.Middle)')
    return operation.replace('BIT 7,','BIT @ActionComponentEncodeConst.SignBit,').replace('SET 7,','SET @ActionComponentEncodeConst.SignBit,')
